<!doctype html>
<html lang="es">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reporte de Planilla</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef2ff;color:#1e293b;font:11px Arial,sans-serif}.acciones{max-width:1120px;margin:18px auto;text-align:right}.acciones a,.acciones button{border:0;border-radius:9px;padding:10px 15px;text-decoration:none;font-weight:700}.acciones a{background:#fff;color:#334155}.acciones button{background:#4f46e5;color:#fff}.hoja{max-width:1120px;margin:0 auto 25px;background:#fff;padding:28px;box-shadow:0 12px 35px #312e8120}.cabecera{display:flex;justify-content:space-between;gap:20px;border-bottom:2px solid #c7d2fe;padding-bottom:14px}.cabecera h1{margin:0;color:#312e81}.cabecera p{margin:4px 0;color:#64748b}.filtros{text-align:right}.resumen{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:15px 0}.tarjeta{border:1px solid #c7d2fe;border-radius:9px;padding:10px;background:#eef2ff}.tarjeta small{display:block;color:#6366f1;text-transform:uppercase;font-weight:700}.tarjeta b{display:block;margin-top:4px;font-size:16px}.bloques{display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin-bottom:18px}.bloque{border:1px solid #e2e8f0;border-radius:9px;overflow:hidden}.bloque h2{font-size:13px;margin:0;padding:10px;background:#f8fafc}.tabla{width:100%;border-collapse:collapse}.tabla th{background:#eef2ff;color:#475569;text-align:left;text-transform:uppercase;font-size:9px}.tabla th,.tabla td{border-bottom:1px solid #e2e8f0;padding:6px 5px;vertical-align:top}.tabla small{display:block;color:#64748b;margin-top:2px}.numero{text-align:right;white-space:nowrap}.detalle-seccion{page-break-before:auto}.pie{display:flex;justify-content:space-between;margin-top:18px;border-top:1px solid #e2e8f0;padding-top:10px;color:#64748b}.vacio{text-align:center;padding:20px;color:#64748b}@page{size:A4 landscape;margin:8mm}@media print{body{background:#fff}.acciones{display:none}.hoja{max-width:none;margin:0;padding:0;box-shadow:none}}
</style></head>
<body><div class="acciones"><a href="javascript:history.back()">Volver</a> <button onclick="window.print()">Imprimir</button></div><main class="hoja">
<header class="cabecera"><div><h1><?= htmlspecialchars($institucion['nombre']) ?></h1><p><?= htmlspecialchars($institucion['ruc'] ?? '') ?></p><p><?= htmlspecialchars($institucion['direccion'] ?? '') ?></p></div><div class="filtros"><b>REPORTE CONSOLIDADO DE PLANILLA</b><p>Emitido: <?= date('d/m/Y H:i') ?></p><p><?= $anio ? 'Año ' . $anio : 'Todos los años' ?> · <?= $periodo ? 'Período específico' : 'Todos los períodos' ?> · <?= $persona ? 'Trabajador individual' : 'Todos los trabajadores' ?></p><p>Estado: <?= htmlspecialchars($estadoCuenta) ?></p></div></header>
<section class="resumen"><div class="tarjeta"><small>Trabajadores</small><b><?= number_format((int)$totales['trabajadores']) ?></b></div><div class="tarjeta"><small>Costo neto</small><b>S/ <?= number_format($totales['neto'],2) ?></b></div><div class="tarjeta"><small>Total pagado</small><b>S/ <?= number_format($totales['pagado'],2) ?></b></div><div class="tarjeta"><small>Saldo pendiente</small><b>S/ <?= number_format($totales['saldo'],2) ?></b></div></section>
<section class="bloques"><div class="bloque"><h2><?= $anio ? 'Resumen anual ' . $anio : 'Costo por mes' ?></h2><table class="tabla"><thead><tr><th>Mes</th><th class="numero">Base</th><th class="numero">Bonif.</th><th class="numero">Desc.</th><th class="numero">Neto</th><th class="numero">Pagado</th><th class="numero">Pendiente</th></tr></thead><tbody><?php foreach ($resumenMensual as $mes): ?><tr><td><?= htmlspecialchars($mes['etiqueta']) ?></td><td class="numero">S/ <?= number_format($mes['base'],2) ?></td><td class="numero">S/ <?= number_format($mes['bonificaciones'],2) ?></td><td class="numero">S/ <?= number_format($mes['descuentos'],2) ?></td><td class="numero"><b>S/ <?= number_format($mes['neto'],2) ?></b></td><td class="numero">S/ <?= number_format($mes['pagado'],2) ?></td><td class="numero">S/ <?= number_format($mes['saldo'],2) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="bloque"><h2>Pagos por medio</h2><table class="tabla"><thead><tr><th>Medio</th><th>Operaciones</th><th class="numero">Importe</th></tr></thead><tbody><?php foreach ($pagosPorMedio as $medio): ?><tr><td><?= htmlspecialchars($medio['medio_pago']) ?></td><td><?= (int)$medio['cantidad'] ?></td><td class="numero">S/ <?= number_format((float)$medio['total'],2) ?></td></tr><?php endforeach; ?><tr><td colspan="2"><b>Total vigente</b></td><td class="numero"><b>S/ <?= number_format($totalMedios,2) ?></b></td></tr><?php if ((int)$pagosAnulados['cantidad'] > 0): ?><tr><td>ANULADOS</td><td><?= (int)$pagosAnulados['cantidad'] ?></td><td class="numero">S/ <?= number_format((float)$pagosAnulados['total'],2) ?></td></tr><?php endif; ?></tbody></table></div></section>
<section class="detalle-seccion"><h2>Detalle consolidado</h2><table class="tabla"><thead><tr><th>Trabajador</th><th>Período</th><th class="numero">Base</th><th class="numero">Bonif.</th><th class="numero">Desc.</th><th class="numero">Neto</th><th class="numero">Pagado</th><th class="numero">Saldo</th><th>Estado</th></tr></thead><tbody><?php foreach ($filas as $fila): ?><tr><td><b><?= htmlspecialchars($fila['trabajador']) ?></b><small><?= htmlspecialchars(($fila['codigo_trabajador'] ?: 'Sin código') . ' · ' . $fila['cargo']) ?></small></td><td><?= htmlspecialchars($fila['periodo']) ?><small><?= htmlspecialchars($fila['fecha_inicio'] . ' a ' . $fila['fecha_fin']) ?></small></td><td class="numero">S/ <?= number_format((float)$fila['monto_base'],2) ?></td><td class="numero">S/ <?= number_format((float)$fila['bonificaciones'],2) ?></td><td class="numero">S/ <?= number_format((float)$fila['descuentos'],2) ?></td><td class="numero"><b>S/ <?= number_format((float)$fila['monto_pagar'],2) ?></b></td><td class="numero">S/ <?= number_format((float)$fila['monto_pagado'],2) ?></td><td class="numero">S/ <?= number_format((float)$fila['saldo_pendiente'],2) ?></td><td><?= htmlspecialchars($fila['estado']) ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$filas): ?><div class="vacio">No existen registros para los filtros seleccionados.</div><?php endif; ?></section>
<footer class="pie"><span>Documento interno de control</span><span>Los pagos anulados no forman parte del total pagado.</span></footer></main></body></html>
